insert into public.categories (slug, name, position, published)
select * from (values
  ('branding', 'Branding', 0, true),
  ('web', 'Digital & web', 1, true),
  ('3d', '3D & architecture', 2, true),
  ('audiovisuel', 'Audiovisuel', 3, true),
  ('publicite', 'Publicité', 4, true)
) as v(slug, name, position, published) where not exists (select 1 from public.categories);

